#include <bitset>
#define fi first
#define se second
#define pb push_back
#define mk make_pair
using namespace std;
typedef long long ll;
typedef unsigned long long ull;

ll read_input() {
    char ch = getchar(); ll x = 0, f = 1;
    while (ch < '0' || ch > '9') {
        if (ch == '-') f = -1;
        ch = getchar();
    }
    x = ch - '0';
    while (true) {
        ch = getchar();
        if (ch < '0' || ch > '9') break;
        x = x * 10 + ch - '0';
    }
    return x * f;
}

const ll MOD = 1000000007;

ll multiply_mod(ll a, ll b, ll m) {
    ll result = 0;
    while (b) {
        if (b & 1) result = (result + a) % m;
        b >>= 1;
        a = (a + a) % m;
    }
    return result;
}

ll power_mod(ll a, ll b, ll m) {
    ll result = 1;
    while (b) {
        if (b & 1) result = multiply_mod(result, a, m);
        b >>= 1;
        a = multiply_mod(a, a, m);
    }
    return result;
}

int main() {
    ll p = read_input();
    ll k = read_input();
    ll ret;
    if (k == 0) {
        ret = power_mod(p, p - 1, MOD);
    } else if (k == 1) {
        ret = power_mod(p, p, MOD);
    } else {
        ll l = 1, cur = k;
        while (cur != 1) {
            cur = (cur * k) % p;
            l++;
        }
        ret = power_mod(p, (p - 1) / l, MOD);
    }
    printf("%lld\n", ret);
    return 0;
}
